  const competenciaDetalle = require("../lib/competencia_detalle.js");
  const capacidad = require("../lib/capacidad.js");
  const perfilesMod = require("../lib/perfiles.js");
  const { PERFILES } = perfilesMod;
  const configRup = require("../lib/config_rup.js");
  // el token de los endpoints protegidos, por cabecera (la vía preferida)
  const CAB_TOKEN = { "x-historico-token": process.env.HISTORICO_TOKEN };
  const redis = crearRedis({});

  /* unidad: un SOCRATA_APP_TOKEN inválido no puede parar la sincronización
     (ago 2026: producción estuvo 14 h con 403 «Invalid app_token specified»
     porque el valor pegado en Vercel no era el correcto). Ante 403 CON token se
     reintenta una vez sin él; si responde, el token se descarta y se cuenta.
     Un 403 SIN token sigue siendo un 403 de verdad. */
  {
    const { crearCliente } = require("../lib/socrata.js");
    const llamadas = [];
    const fetchFalso = async (url, { headers }) => {
      llamadas.push(!!headers["X-App-Token"]);
      if (headers["X-App-Token"]) return { ok: false, status: 403, headers: { get: () => null }, text: async () => "Invalid app_token specified" };
      return { ok: true, status: 200, json: async () => [{ n: "1" }] };
    };
    const cli = crearCliente({ appToken: "MALO", fetchImpl: fetchFalso, dormir: async () => {} });
    const r = await cli.pedir({ "$limit": "1" }, "prueba");
    assert.deepStrictEqual(r, [{ n: "1" }], "con el token rechazado la petición tiene que responder igual, sin él");
    assert.strictEqual(cli.appTokenRechazado(), true);
    assert.deepStrictEqual(llamadas, [true, false], "403 con token → una llamada sin token");
    await cli.pedir({ "$limit": "1" }, "prueba2");
    assert.deepStrictEqual(llamadas.slice(2), [false], "descartado el token, las siguientes van sin él desde el principio");
    // 403 SIN token: bloqueo real, se agota como antes
    const cli403 = crearCliente({ appToken: "", fetchImpl: async () => ({ ok: false, status: 403, headers: { get: () => null }, text: async () => "" }), dormir: async () => {} });
    await assert.rejects(() => cli403.pedir({ "$limit": "1" }, "bloqueo"), /agotados/);
    assert.strictEqual(cli403.appTokenRechazado(), false);
    /* Y EL `*` VA PRIMERO en el $select del keyset: el 16-ago-2026 Socrata empezó
       a rechazar `:id,:updated_at,*` con 400 «Star selections must come at the
       start of the select-list» y producción degradó a $offset (donde se
       quedó sin sincronizar). Se fija el orden con la URL real que arma el
       cliente. */
    const urls = [];
    const cliUrl = crearCliente({ appToken: "", fetchImpl: async (url) => { urls.push(url); return { ok: true, status: 200, json: async () => [] }; }, dormir: async () => {} });
    await cliUrl.paginaMes("2026-01", {}, { pagina: 5, keyset: true });
    await cliUrl.paginaDelta("2026-08-15T00:00:00.000Z", 2026, {}, { pagina: 5, keyset: true });
    for (const u of urls) {
      const sel = decodeURIComponent(new URL(u).searchParams.get("$select") || "");
      assert.ok(sel.startsWith("*"), `el $select del keyset tiene que empezar por «*» (Socrata lo exige desde ago 2026): «${sel}»`);
      assert.ok(/:id/.test(sel) && /:updated_at/.test(sel), "el keyset sigue necesitando :id y :updated_at");
    }
    console.log("· unidad socrata: token inválido → 403 con token, 200 sin él, se descarta y se cuenta; 403 sin token sigue siendo bloqueo; $select del keyset con * primero");
  }

  /* unidad: el empaquetador respeta los 500 KB comprimidos y no pierde filas */
  {
    const grandes = Array.from({ length: 9000 }, (_, i) => ({ _k: `k${i}`, blob: crypto.randomBytes(120).toString("hex") }));
    const paquetes = empaquetar(grandes);
    assert.ok(paquetes.length > 1, "empaquetar debe partir lotes grandes");
    for (const p of paquetes) assert.ok(Buffer.byteLength(p, "base64") <= CHUNK_MAX_COMPRIMIDO, "chunk sobre el límite de 500 KB");
    const vueltas = paquetes.flatMap((p) => descomprimir(p));
    assert.strictEqual(vueltas.length, grandes.length, "el empaquetador perdió filas");
    console.log(`· unidad empaquetar: ${paquetes.length} chunks ≤500 KB, ${vueltas.length} filas conservadas`);
  }

  /* unidad: la detección de anticipo no cruza frases ni ignora negaciones */
